package main

import (
	"fmt"
)

func main() {
	var b int
	if _, err := fmt.Scan(&b); err != nil {
		return
	}

	if b == 1 {
		fmt.Println(1)
		return
	}

	counter := 0
	for i := 2; i*i <= b; i++ {
		if b%i == 0 {
			if i*i == b {
				counter++
			} else {
				counter += 2
			}
		}
	}

	fmt.Println(counter + 2)
}

