import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		b, _ := strconv.Atoi(line)

		if b == 1 {
			fmt.Println(1)
			return
		}

		counter := 0
		sqrtB := int(math.Sqrt(float64(b)))

		for i := 2; i <= sqrtB; i++ {
			if b%i == 0 {
				if i*i == b {
					counter++
				} else {
					counter += 2
				}
			}
		}

		fmt.Println(counter + 2)
	}
